function decodeBase64Url(value) {
  const base64 = value.replace(/-/g, "+").replace(/_/g, "/");
  const binary = atob(base64 + "=".repeat((4 - (base64.length % 4)) % 4));
  return Uint8Array.from(binary, (char) => char.charCodeAt(0));
}
function encodeBase64Url(value) {
  return btoa(String.fromCharCode(...new Uint8Array(value)))
    .replace(/\+/g, "-")
    .replace(/\//g, "_")
    .replace(/=+$/g, "");
}
function publicKeyOptions(json) {
  const options = JSON.parse(json);
  options.challenge = decodeBase64Url(options.challenge);
  if (options.user?.id) options.user.id = decodeBase64Url(options.user.id);
  if (options.excludeCredentials)
    options.excludeCredentials = options.excludeCredentials.map((item) => ({
      ...item,
      id: decodeBase64Url(item.id),
    }));
  if (options.allowCredentials)
    options.allowCredentials = options.allowCredentials.map((item) => ({
      ...item,
      id: decodeBase64Url(item.id),
    }));
  return options;
}
function serializeCredential(credential) {
  return {
    id: credential.id,
    rawId: encodeBase64Url(credential.rawId),
    type: credential.type,
    authenticatorAttachment: credential.authenticatorAttachment,
    response: {
      clientDataJSON: encodeBase64Url(credential.response.clientDataJSON),
      ...(credential.response.attestationObject
        ? { attestationObject: encodeBase64Url(credential.response.attestationObject) }
        : {}),
      ...(credential.response.authenticatorData
        ? { authenticatorData: encodeBase64Url(credential.response.authenticatorData) }
        : {}),
      ...(credential.response.signature
        ? { signature: encodeBase64Url(credential.response.signature) }
        : {}),
      ...(credential.response.userHandle
        ? { userHandle: encodeBase64Url(credential.response.userHandle) }
        : {}),
      ...(credential.response.getTransports
        ? { transports: credential.response.getTransports() }
        : {}),
    },
    clientExtensionResults: credential.getClientExtensionResults(),
  };
}
async function getPasskeyStatus() {
  return api("/auth/passkeys/me");
}
async function registerPasskey() {
  if (!window.PublicKeyCredential || !navigator.credentials)
    throw new Error(t("passkeyUnsupported"));
  const start = await api("/auth/passkeys/registration/options", { method: "POST", body: "{}" });
  const credential = await navigator.credentials.create({
    publicKey: publicKeyOptions(start.publicKey),
  });
  if (!credential) throw new Error(t("passkeyRegistrationFailed"));
  await api("/auth/passkeys/registration/verify", {
    method: "POST",
    body: JSON.stringify({
      challenge_id: start.challenge_id,
      credential: serializeCredential(credential),
      label:
        navigator.userAgent.includes("iPhone") || navigator.userAgent.includes("Mac")
          ? "This Apple device"
          : "This device",
    }),
  });
  await refreshPasskeyStatus();
}
async function refreshPasskeyStatus() {
  const status = await getPasskeyStatus();
  const text = $("#passkeyStatus");
  if (text) text.textContent = status.enabled ? t("passkeyEnabled") : t("passkeyMissing");
  return status;
}
async function ensurePasskey() {
  let status = await getPasskeyStatus();
  if (!status.enabled) {
    await registerPasskey();
    status = await getPasskeyStatus();
  }
  if (!status.enabled) throw new Error(t("passkeyRegistrationFailed"));
}
async function authenticateWithPasskey(purpose) {
  await ensurePasskey();
  const start = await api("/auth/passkeys/authentication/options", {
    method: "POST",
    body: JSON.stringify({ purpose }),
  });
  const credential = await navigator.credentials.get({
    publicKey: publicKeyOptions(start.publicKey),
  });
  if (!credential) throw new Error(t("passkeyVerifyFailed"));
  const result = await api("/auth/passkeys/authentication/verify", {
    method: "POST",
    body: JSON.stringify({
      challenge_id: start.challenge_id,
      credential: serializeCredential(credential),
    }),
  });
  return result.proof;
}

let profileAvatarObjectUrl = null;
let profileAvatarRequestId = 0;
async function renderProfile(profile) {
  user = profile;
  const form = $("#profileForm");
  form.elements.full_name.value = profile.full_name || "";
  form.elements.age.value = profile.age ?? "";
  form.elements.bio.value = profile.bio || "";
  const avatar = $("#profileAvatar");
  const initials = $("#profileInitials");
  const requestId = ++profileAvatarRequestId;
  avatar.hidden = true;
  initials.hidden = false;
  initials.textContent = (profile.full_name || "?")
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((part) => part[0])
    .join("")
    .toUpperCase();
  if (profile.avatar_url) {
    try {
      const response = await fetch(profile.avatar_url, {
        headers: { Authorization: `Bearer ${accessToken}` },
      });
      if (!response.ok) throw new Error("Profile photo unavailable");
      const objectUrl = URL.createObjectURL(await response.blob());
      if (requestId !== profileAvatarRequestId) {
        URL.revokeObjectURL(objectUrl);
        return;
      }
      if (profileAvatarObjectUrl) URL.revokeObjectURL(profileAvatarObjectUrl);
      profileAvatarObjectUrl = objectUrl;
      avatar.src = objectUrl;
      avatar.alt = profile.full_name || t("profilePhotoLabel");
      avatar.hidden = false;
      initials.hidden = true;
    } catch {
      /* Keep the initials fallback if the private photo cannot be loaded. */
    }
  }
}

async function loadDashboard() {
  if (!accessToken) {
    updateAuthUI();
    return;
  }
  const token = accessToken;
  const requestId = ++dashboardRequestId;
  const isCurrent = () => token === accessToken && requestId === dashboardRequestId;
  const coursesArea = $("#enrolledCourses");
  try {
    const account = await api("/auth/me");
    if (!isCurrent()) return;
    user = account;
    updateAuthUI();
    const catalog = loadCourses();
    if (user.account_type === "author") {
      await Promise.all([catalog, loadInstructorCourses()]);
      return;
    }
    if (!coursesArea.hasChildNodes()) {
      coursesArea.innerHTML = `<div class="course-placeholder">${escapeHtml(t("dashboardTitle"))}…</div>`;
    }
    Promise.allSettled([
      api("/recommendations/me?limit=4"),
      renderProfile(user),
      refreshPasskeyStatus(),
      catalog,
    ]).then(([result]) => {
      if (!isCurrent()) return;
      const data = result.status === "fulfilled" ? result.value : null;
      renderRecommendations(data?.recommendations || [], data?.ai_powered || false);
    });
    const enrollments = await listEnrollments();
    if (!isCurrent()) return;
    learnerEnrollments = enrollments;
    if (resumeLesson && !enrollments.some(({ course_id }) => course_id === resumeLesson.courseId)) {
      saveResumeLesson(null);
    }
    renderEnrollmentList(enrollments);

    const entries = await Promise.all(
      enrollments.map(async (enrollment) => {
        const [progress, certificate] = await Promise.all([
          api(`/courses/${enrollment.course_id}/progress/me`).catch(() => null),
          api(`/courses/${enrollment.course_id}/certificate/me`).catch(() => null),
        ]);
        return { enrollment, progress, certificate };
      }),
    );
    if (isCurrent()) renderLearningOverview(entries);
  } catch (error) {
    if (!isCurrent()) return;
    coursesArea.innerHTML = `<div class="course-placeholder">${escapeHtml(error.message || t("genericError"))}</div>`;
    if (error.status === 401) {
      accessToken = null;
      user = null;
      learnerEnrollments = [];
      showMyCourses();
      localStorage.removeItem("studyflow-token");
      updateAuthUI();
    }
  }
}

function renderEnrollmentList(enrollments) {
  const container = $("#enrolledCourses");
  container.innerHTML = enrollments.length
    ? enrollments
        .map(
          ({ course_id, course_title }) =>
            `<article class="learner-list-card"><div><b>${escapeHtml(course_title)}</b></div><button type="button" class="button button-outline button-small" data-open-enrollment="${escapeHtml(course_id)}">${escapeHtml(t("openCourse"))}</button></article>`,
        )
        .join("")
    : `<div class="course-placeholder">${escapeHtml(t("emptyEnrollments"))}</div>`;
}
function renderLearnerAssignment(lesson, assignment) {
  const submission = assignment.my_submission;
  const status =
    submission?.status === "graded"
      ? `<p class="assignment-result assignment-graded">${escapeHtml(t("assignmentGradedStatus"))}: ${submission.score}/${assignment.max_score}${submission.feedback ? ` · ${escapeHtml(submission.feedback)}` : ""}</p>`
      : submission
        ? `<p class="assignment-result">${escapeHtml(t("assignmentPendingStatus"))}</p>`
        : "";
  return `<section class="learner-assignment"><h4>${escapeHtml(assignment.title)}</h4><p>${escapeHtml(assignment.instructions)}</p>${status}<form class="assignment-submit-form" data-assignment-submit data-course-id="${lesson.course_id}" data-lesson-id="${lesson.id}"><label><span>${escapeHtml(t("assignmentAnswerLabel"))}</span><textarea name="answer" rows="4" maxlength="20000" required>${escapeHtml(submission?.answer || "")}</textarea></label><button class="button button-outline" type="submit">${escapeHtml(t(submission ? "assignmentResubmitButton" : "assignmentSubmitButton"))}</button><p class="assignment-form-message" role="status"></p></form></section>`;
}

function mountLessonNote(panel, accountId, lessonId) {
  const c = lessonNoteCopy[language];
  const key = `studyflow-note-${accountId}-${lessonId}`;
  const fieldId = `note-${escapeHtml(lessonId)}`;
  panel.insertAdjacentHTML(
    "beforeend",
    `<form class="lesson-note-form"><label for="${fieldId}">${escapeHtml(c.title)}</label><small id="${fieldId}-hint">${escapeHtml(c.hint)}</small><textarea id="${fieldId}" aria-describedby="${fieldId}-hint" name="note" rows="3" maxlength="${NOTE_LIMIT}" placeholder="${escapeHtml(c.placeholder)}"></textarea><button class="button button-outline button-small" type="submit" disabled>${escapeHtml(c.save)}</button><p class="lesson-note-status" role="status"></p></form>`,
  );
  const form = panel.querySelector(".lesson-note-form");
  const { note } = form.elements;
  const save = form.querySelector("button");
  const status = form.querySelector(".lesson-note-status");
  let saved = "";
  try {
    saved = localStorage.getItem(key) ?? "";
    note.value = saved;
  } catch {
    status.textContent = c.loadError;
  }
  note.addEventListener("input", () => {
    save.disabled = note.value === saved;
    status.textContent = "";
  });
  form.addEventListener("submit", (event) => {
    event.preventDefault();
    if (user?.id !== accountId || save.disabled) return;
    const value = note.value.trim();
    try {
      if (value) localStorage.setItem(key, value);
      else localStorage.removeItem(key);
      saved = value;
      note.value = value;
      save.disabled = true;
      status.textContent = c.saved;
    } catch {
      status.textContent = c.saveError;
    }
  });
}

function renderLearnerCourse(enrollment, lessons, progress, signal, rememberInitialLesson) {
  const container = $("#activeCourse");
  const courseId = enrollment.course_id;
  const completed =
    progress.total_lessons > 0 && progress.completed_lessons === progress.total_lessons;
  const items = lessons
    .map((lesson) => {
      const done = progress.completed_lesson_ids.includes(lesson.id);
      const videoRequired =
        lesson.resource_type === "video" &&
        Boolean(lesson.resource_url || lesson.external_video_url);
      return `<div class="lesson-item"><span class="lesson-status ${done ? "done" : ""}">${done ? "✓" : "○"}</span><div class="lesson-entry"><span class="lesson-name">${escapeHtml(lesson.title)}</span></div>${!done && videoRequired ? `<small class="video-watch-meter" data-watch-progress="${lesson.id}">${videoWatchCopy[language]}</small>` : ""}${done ? `<span class="completed-label">${t("completed")}</span>` : `<button class="button button-outline" data-complete="${lesson.id}" data-course="${enrollment.course_id}" ${videoRequired ? "disabled" : ""}>${videoRequired ? videoWatchCopy[language] : t("markComplete")}</button>`}<button class="button button-outline quiz-open" data-quiz-course="${enrollment.course_id}" data-quiz-lesson="${lesson.id}">${t("openQuiz")}</button><button class="lesson-toggle" data-toggle="lesson-${lesson.id}" aria-label="${t("openLesson")}">⌄</button><div class="lesson-content" id="lesson-${lesson.id}"><p class="lesson-copy">${escapeHtml(lesson.content)}</p></div><div class="quiz-area" id="quiz-${lesson.id}" hidden></div></div>`;
    })
    .join("");
  container.innerHTML = `<article class="enrolled-card" id="course-${enrollment.course_id}"><div class="enrolled-top"><div><div class="section-label">${t("progress")}</div><h3 tabindex="-1">${escapeHtml(enrollment.course_title)}</h3><p>${lessons.length} ${t("lessonCount")}</p></div><strong>${progress.progress_percent}%</strong></div><div class="progress-track course-progress" style="--progress:${progress.progress_percent}%"><span></span></div><div class="progress-summary"><span>${progress.completed_lessons}/${progress.total_lessons} ${t("completed")}</span><span>${progress.progress_percent}%</span></div><div class="lessons-list">${items || `<div class="panel-empty">${t("emptyLessons")}</div>`}</div><div class="course-actions"><div class="course-completion-actions">${progress.total_lessons > 0 ? `<p class="exam-unavailable">${escapeHtml(t(completed ? "loadingCourse" : "finalExamLocked"))}</p>` : ""}</div></div></article>`;

  const lessonById = new Map(lessons.map((lesson) => [lesson.id, lesson]));
  container.querySelectorAll(".lesson-content").forEach((host) => {
    const lesson = lessonById.get(host.id.slice("lesson-".length));
    host.insertAdjacentHTML(
      "afterbegin",
      renderLessonBanner(lesson) + contentTranslationNotice(lesson),
    );
    host.insertAdjacentHTML("beforeend", renderLessonResource(lesson));
    setupVideoCompletion(host.closest(".lesson-item"), courseId, lesson);
  });

  bindLearnerCourseActions(container, enrollment, lessonById, signal, rememberInitialLesson);
}

function renderLearningOverview(entries) {
  const completeEntries = entries.filter(
    ({ progress }) =>
      progress?.total_lessons > 0 && progress.completed_lessons === progress.total_lessons,
  );
  const completedLessons = entries.reduce(
    (sum, { progress }) => sum + (progress?.completed_lessons ?? 0),
    0,
  );
  const certificates = entries.filter(({ certificate }) => certificate);
  const summaryItems = [
    [entries.length, t("courseCountLabel")],
    [
      entries.every(({ progress }) => progress) ? completeEntries.length : "–",
      t("completedCoursesCountLabel"),
    ],
    [
      entries.every(({ progress }) => progress) ? completedLessons : "–",
      t("completedLessonsCountLabel"),
    ],
    [certificates.length, t("certificatesCountLabel")],
  ];
  $("#learningOverview").innerHTML = summaryItems
    .map(
      ([count, label]) =>
        `<article class="learning-stat"><b>${count}</b><span>${escapeHtml(label)}</span></article>`,
    )
    .join("");
  $("#completedCourseList").innerHTML = completeEntries.length
    ? completeEntries
        .map(
          ({ enrollment, progress }) =>
            `<article class="learner-list-card"><div><b>${escapeHtml(enrollment.course_title)}</b><span>${progress.completed_lessons}/${progress.total_lessons} ${escapeHtml(t("completed"))}</span></div><button type="button" class="button button-outline button-small" data-open-enrollment="${escapeHtml(enrollment.course_id)}">${escapeHtml(t("openCourse"))}</button></article>`,
        )
        .join("")
    : `<p class="panel-empty">${escapeHtml(t("emptyCompletedCourses"))}</p>`;
  $("#myCertificateList").innerHTML = certificates.length
    ? certificates
        .map(({ certificate }) => {
          const issuedDate = new Intl.DateTimeFormat(language, {
            year: "numeric",
            month: "short",
            day: "numeric",
          }).format(new Date(certificate.issued_at));
          return `<article class="learner-list-card certificate-list-card"><div><b>${escapeHtml(certificate.course_title)}</b><span>${escapeHtml(t("certificateCode"))}: ${escapeHtml(certificate.certificate_code)}</span><span>${escapeHtml(t("issuedOn"))}: ${escapeHtml(issuedDate)}</span></div><a class="button button-outline button-small" href="/app/verify.html?code=${encodeURIComponent(certificate.certificate_code)}">${escapeHtml(t("navVerifyCertificate"))}</a></article>`;
        })
        .join("")
    : `<p class="panel-empty">${escapeHtml(t("emptyCertificates"))}</p>`;
}

function bindLearnerCourseActions(
  container,
  enrollment,
  lessonById,
  signal,
  rememberInitialLesson,
) {
  const { course_id: courseId, course_title: courseTitle } = enrollment;
  container.querySelectorAll("[data-complete]").forEach((button) =>
    button.addEventListener("click", async () => {
      button.disabled = true;
      try {
        await api(
          `/courses/${button.dataset.course}/progress/lessons/${button.dataset.complete}/complete`,
          { method: "POST" },
        );
        if (activeCourseId === courseId) openLearnerCourse(courseId, { openLesson: false });
        loadDashboard();
      } catch (error) {
        button.disabled = false;
        alert(error.message);
      }
    }),
  );
  container
    .querySelectorAll("[data-quiz-course]")
    .forEach((button) =>
      button.addEventListener("click", () =>
        openQuiz(button.dataset.quizCourse, button.dataset.quizLesson),
      ),
    );
  container.querySelectorAll("[data-toggle]").forEach((button) =>
    button.addEventListener("click", (event) => {
      const panel = document.getElementById(button.dataset.toggle);
      const opened = panel.classList.toggle("open");
      const lessonId = panel.id.slice("lesson-".length);
      button.textContent = opened ? "⌃" : "⌄";
      if (opened && (event.isTrusted || rememberInitialLesson)) {
        saveResumeLesson({
          courseId,
          courseTitle,
          lessonId,
          lessonTitle: lessonById.get(lessonId).title,
        });
      }
      if (opened && user?.id && !panel.querySelector(".lesson-note-form")) {
        mountLessonNote(panel, user.id, lessonId);
      }
      if (opened && !panel.dataset.assignmentLoaded) {
        panel.dataset.assignmentLoaded = "true";
        api(
          `/courses/${courseId}/lessons/${lessonId}/assignment?language=${encodeURIComponent(language)}`,
          { signal: AbortSignal.any([signal, AbortSignal.timeout(CATALOG_REQUEST_TIMEOUT_MS)]) },
        )
          .then((assignment) => {
            if (!assignment || !panel.isConnected) return;
            panel.insertAdjacentHTML(
              "beforeend",
              renderLearnerAssignment({ id: lessonId, course_id: courseId }, assignment),
            );
            bindLearnerAssignment(panel.querySelector("[data-assignment-submit]"), courseId);
          })
          .catch(() => {
            delete panel.dataset.assignmentLoaded;
          });
      }
      button.setAttribute("aria-label", opened ? t("hideLesson") : t("openLesson"));
    }),
  );
}
function bindLearnerAssignment(form, courseId) {
  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const message = form.querySelector(".assignment-form-message");
    try {
      await api(
        `/courses/${form.dataset.courseId}/lessons/${form.dataset.lessonId}/assignment/submissions`,
        { method: "POST", body: JSON.stringify({ answer: form.elements.answer.value }) },
      );
      if (form.isConnected) await openLearnerCourse(courseId);
    } catch (error) {
      message.textContent = error.message || t("studioError");
    }
  });
}

function renderCourseCompletion(container, courseId, exam, certificate, review) {
  container.querySelector(".course-completion-actions").innerHTML = exam
    ? exam.passed
      ? `<button class="button button-outline certificate-button" data-certificate="${courseId}" data-issued="${certificate ? "true" : "false"}">${t(certificate ? "viewCertificate" : "certificateButton")}</button>`
      : `<button class="button button-dark final-exam-button" data-final-exam="${courseId}">${t("finalExam")}${exam.latest_score !== null ? ` · ${exam.latest_score}%` : ""}</button>`
    : `<p class="exam-unavailable">${escapeHtml(t("finalExamUnavailable"))}</p>`;
  container
    .querySelector(".enrolled-card")
    .insertAdjacentHTML(
      "beforeend",
      `<form class="course-review-form" data-review-course="${courseId}"><h4>${escapeHtml(t("reviewTitle"))}</h4><label><span>${escapeHtml(t("reviewRating"))}</span><select name="rating">${[5, 4, 3, 2, 1].map((rating) => `<option value="${rating}" ${Number(review?.rating || 5) === rating ? "selected" : ""}>${rating} ★</option>`).join("")}</select></label><label><span>${escapeHtml(t("reviewComment"))}</span><textarea name="comment" rows="2" maxlength="2000" placeholder="${escapeHtml(t("reviewPlaceholder"))}">${escapeHtml(review?.comment || "")}</textarea></label><button class="button button-outline" type="submit">${escapeHtml(t("submitReview"))}</button><p class="review-form-message" role="status"></p></form>`,
    );
  container
    .querySelectorAll("[data-final-exam]")
    .forEach((button) =>
      button.addEventListener("click", () => openFinalExam(button.dataset.finalExam)),
    );
  container.querySelectorAll("[data-certificate]").forEach((button) =>
    button.addEventListener("click", async () => {
      button.disabled = true;
      try {
        let certificate;
        if (button.dataset.issued === "true")
          certificate = await api(`/courses/${button.dataset.certificate}/certificate/me`);
        else {
          const proof = await authenticateWithPasskey("certificate");
          certificate = await api(`/courses/${button.dataset.certificate}/certificate`, {
            method: "POST",
            headers: { "X-Passkey-Proof": proof },
          });
        }
        showCertificate(certificate);
        button.dataset.issued = "true";
        button.textContent = t("viewCertificate");
        loadDashboard();
      } catch (error) {
        alert(error.message || t("certificateError"));
      } finally {
        button.disabled = false;
      }
    }),
  );
  container.querySelectorAll("[data-review-course]").forEach((form) =>
    form.addEventListener("submit", async (event) => {
      event.preventDefault();
      const message = form.querySelector(".review-form-message");
      const values = Object.fromEntries(new FormData(form));
      try {
        await api(`/courses/${form.dataset.reviewCourse}/reviews/me`, {
          method: "PUT",
          body: JSON.stringify({ rating: Number(values.rating), comment: values.comment || null }),
        });
        message.textContent = t("reviewSaved");
      } catch (error) {
        message.textContent = error.message || t("studioError");
      }
    }),
  );
}
function quizLockText(lock) {
  if (lock.reason === "passed") return t("quizAlreadyPassed");
  if (!lock.retry_at) return t("quizRetryLater");
  const date = new Date(lock.retry_at).toLocaleString(language, {
    dateStyle: "medium",
    timeStyle: "short",
  });
  return t("quizRetryAt").replace("{date}", date);
}

async function openQuiz(courseId, lessonId) {
  const panel = document.getElementById(`quiz-${lessonId}`);
  panel.hidden = false;
  panel.innerHTML = `<p class="panel-empty">${t("quizLoading")}</p>`;
  try {
    const quiz = await api(
      `/courses/${courseId}/lessons/${lessonId}/quiz?language=${encodeURIComponent(language)}`,
    );
    panel.innerHTML = `<div class="quiz-heading"><div><h4>${escapeHtml(quiz.title || t("quizTitle"))}</h4><p>${t("passingScore")}: ${quiz.passing_score}%</p></div></div><div class="attempt-history"></div>`;
    const history = panel.querySelector(".attempt-history");
    const attemptsUrl = `/courses/${courseId}/lessons/${lessonId}/quiz/attempts`;
    let historyVersion = 0;
    const refreshHistory = async () => {
      const version = ++historyVersion;
      const attempts = await api(`${attemptsUrl}/me`).catch(() => null);
      if (attempts && version === historyVersion) renderQuizHistory(history, attempts);
    };
    if (quiz.attempt_lock) {
      const status = document.createElement("p");
      status.className = "quiz-result";
      status.setAttribute("role", "status");
      status.textContent = quizLockText(quiz.attempt_lock);
      history.before(status);
      void refreshHistory();
      return;
    }
    const presentedQuestions = shuffled(quiz.questions).map(shuffledQuestion);
    const questions = presentedQuestions
      .map(
        (question, index) =>
          `<fieldset class="quiz-question"><legend>${index + 1}. ${escapeHtml(question.prompt)}</legend><div class="quiz-choices">${question.choices.map((choice, choiceIndex) => `<label><input type="radio" name="${question.id}" value="${choiceIndex}" required><span><b>${choiceLetter(choiceIndex)}.</b> ${escapeHtml(choice)}</span></label>`).join("")}</div></fieldset>`,
      )
      .join("");
    history.insertAdjacentHTML(
      "beforebegin",
      `<p class="quiz-hint">${t("selectAnswers")} ${escapeHtml(t("shuffleNote"))}</p><form class="quiz-form" data-quiz-id="${quiz.id}">${questions}<button class="button button-dark" type="submit">${t("submitQuiz")}</button><p class="quiz-result" role="status"></p></form><section class="quiz-feedback" hidden></section>`,
    );
    const form = panel.querySelector("[data-quiz-id]");
    const submit = form.querySelector("button[type=submit]");
    const feedback = panel.querySelector(".quiz-feedback");
    const hint = panel.querySelector(".quiz-hint");
    form.addEventListener("submit", async (event) => {
      event.preventDefault();
      if (submit.disabled || !form.reportValidity()) return;
      const answerMap = new FormData(form);
      const answers = presentedQuestions.map((question) => ({
        question_id: question.id,
        selected_index: question.choiceOrder[Number(answerMap.get(question.id))],
      }));
      submit.disabled = true;
      const result = form.querySelector(".quiz-result");
      try {
        const attempt = await api(attemptsUrl, {
          method: "POST",
          body: JSON.stringify({ answers }),
        });
        result.className = `quiz-result ${attempt.passed ? "passed" : "not-passed"}`;
        result.textContent = `${t("result")}: ${attempt.score_percent}% · ${attempt.correct_count}/${attempt.total_questions} ${t("correctAnswers")} — ${t(attempt.passed ? "passed" : "notPassed")}`;
        if (attempt.attempt_lock) result.append(` · ${quizLockText(attempt.attempt_lock)}`);
        hint.remove();
        form.replaceChildren(result);
        renderQuizMistakes(feedback, attempt.mistakes ?? [], presentedQuestions, lessonId);
        void refreshHistory();
      } catch (error) {
        if (form.isConnected && [409, 429].includes(error.status)) {
          void openQuiz(courseId, lessonId);
          return;
        }
        result.textContent = error.message || t("quizError");
        submit.disabled = false;
      }
    });
    void refreshHistory();
  } catch (error) {
    panel.innerHTML = `<p class="panel-empty">${error.status === 404 ? t("noQuiz") : t("quizError")}</p>`;
  }
}

function renderQuizMistakes(container, mistakes, questions, lessonId) {
  const byQuestion = new Map(mistakes.map((mistake) => [mistake.question_id, mistake]));
  const items = questions.flatMap((question, index) => {
    const mistake = byQuestion.get(question.id);
    if (!mistake) return [];
    const selected = question.choices[question.choiceOrder.indexOf(mistake.selected_index)];
    const correct = question.choices[question.choiceOrder.indexOf(mistake.correct_index)];
    if (selected === undefined || correct === undefined) return [];
    const explanation = mistake.explanation
      ? `<p class="quiz-feedback-explanation">${escapeHtml(mistake.explanation)}</p>`
      : "";
    return [
      `<article><b>${index + 1}. ${escapeHtml(question.prompt)}</b><p><strong>${escapeHtml(t("yourAnswer"))}</strong> ${escapeHtml(selected)}</p><p><strong>${escapeHtml(t("correctAnswer"))}</strong> ${escapeHtml(correct)}</p>${explanation}</article>`,
    ];
  });
  container.hidden = !items.length;
  if (!items.length) {
    container.replaceChildren();
    return;
  }
  container.innerHTML = `<h5>${escapeHtml(t("quizMistakes"))}</h5>${items.join("")}<button type="button" class="button button-outline button-small">${escapeHtml(t("reviewQuizLesson"))}</button>`;
  container.querySelector("button").addEventListener("click", () => {
    const lesson = document.getElementById(`lesson-${lessonId}`);
    const toggle = lesson.closest(".lesson-item").querySelector("[data-toggle]");
    if (!lesson.classList.contains("open")) toggle.click();
    toggle.focus({ preventScroll: true });
    lesson.scrollIntoView({ behavior: "instant", block: "start" });
  });
}

function renderQuizHistory(container, attempts) {
  container.innerHTML = `<h5>${t("previousAttempts")}</h5>${
    attempts.length
      ? attempts
          .slice(0, 5)
          .map(
            (attempt, index) =>
              `<p>${index + 1}. ${attempt.score_percent}% · ${attempt.correct_count}/${attempt.total_questions} ${t("correctAnswers")} · ${t(attempt.passed ? "passed" : "notPassed")}</p>`,
          )
          .join("")
      : `<p>${t("noAttempts")}</p>`
  }`;
}

function renderRecommendations(recommendations, aiPowered = false) {
  const container = $("#recommendationList");
  const mode = `<p class="ai-recommendation-mode">${escapeHtml(t(aiPowered ? "aiRecommendation" : "localRecommendation"))}</p>`;
  if (!recommendations.length) {
    container.innerHTML = `${mode}<div class="panel-empty">${t("emptyRecommendations")}</div>`;
    return;
  }
  container.innerHTML =
    mode +
    recommendations
      .map(
        (item) =>
          `<article class="recommendation-card"><h4>${escapeHtml(item.title)}</h4><p>${escapeHtml(item.description || "")}</p><p class="reasons">${escapeHtml((item.reasons || []).join(" · "))}</p><button class="button button-outline" data-recommend="${item.course_id}">${t("enroll")}</button></article>`,
      )
      .join("");
  container.querySelectorAll("[data-recommend]").forEach((button) => {
    const item = recommendations.find(
      (candidate) => candidate.course_id === button.dataset.recommend,
    );
    if (!item) return;
    const level = document.createElement("small");
    level.className = "recommendation-level";
    level.textContent = `${t("recommendedLevel")}: ${humanLevel(item.level)}`;
    button.before(level);
  });
  container.querySelectorAll("[data-recommend]").forEach((button) =>
    button.addEventListener("click", async () => {
      button.disabled = true;
      try {
        await openLearnerCourse(button.dataset.recommend, { price: 0 });
        button.disabled = false;
      } catch (error) {
        button.disabled = false;
        alert(error.message);
      }
    }),
  );
}
function updateLanguagePreference() {
  if (accessToken)
    return api("/auth/me", {
      method: "PUT",
      body: JSON.stringify({ preferred_language: language }),
    }).catch(() => {});
}

async function requestSearchRecommendations() {
  const interest = $("#courseSearch").value.trim();
  if (!interest || user?.account_type !== "learner") return;
  try {
    const data = await api(`/recommendations/me?limit=4&interest=${encodeURIComponent(interest)}`);
    renderRecommendations(data.recommendations || [], data.ai_powered || false);
  } catch {}
}

