$("#profilePhotoInput").addEventListener("change", async (event) => {
  const input = event.currentTarget;
  const file = input.files?.[0];
  if (!file) return;
  const message = $("#profileMessage");
  try {
    if (file.size > 10 * 1024 * 1024) throw new Error(t("profilePhotoError"));
    const bitmap = await createImageBitmap(file);
    const side = Math.min(bitmap.width, bitmap.height);
    const canvas = document.createElement("canvas");
    canvas.width = 512;
    canvas.height = 512;
    canvas
      .getContext("2d")
      .drawImage(
        bitmap,
        (bitmap.width - side) / 2,
        (bitmap.height - side) / 2,
        side,
        side,
        0,
        0,
        512,
        512,
      );
    bitmap.close();
    const blob = await new Promise((resolve) => canvas.toBlob(resolve, "image/webp", 0.86));
    if (!blob) throw new Error(t("profilePhotoError"));
    const dataUrl = await new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result);
      reader.onerror = () => reject(new Error(t("profilePhotoError")));
      reader.readAsDataURL(blob);
    });
    const updated = await api("/auth/me/avatar", {
      method: "PUT",
      body: JSON.stringify({ data_url: dataUrl }),
    });
    await renderProfile(updated);
    message.textContent = t("profilePhotoSaved");
  } catch (error) {
    message.textContent = error.message || t("profilePhotoError");
  } finally {
    input.value = "";
  }
});
